{
  "name": "ESP32-CAM 串口相机模块",
  "name_en": "ESP32-CAM Serial Camera Module",
  "manufacturer": "",
  "description": "一种基于 ESP32 的嵌入式小型相机模块，可通过串口传输图像并进行基础成像参数设置。适合实验中的低成本实时预览、简单图像采集、装置观察与流程记录。",
  "description_en": "A compact embedded camera module based on ESP32 that transmits image data over a serial connection and supports basic imaging parameter adjustment. It is suitable for low-cost live preview, simple image capture, setup observation, and experiment documentation in laboratory environments.",
  "tag_hints": [
    "ESP32-CAM",
    "serial imaging",
    "embedded camera module",
    "live preview",
    "exposure control",
    "analog gain control",
    "ROI imaging"
  ],
  "actions": [
    {
      "action_name": "auto-connect_to_usb_device",
      "description": "连接相机的 USB 串口设备。",
      "description_en": "Connect to the camera's USB serial device."
    },
    {
      "action_name": "auto-calculate_base64_length",
      "description": "计算指定图像尺寸对应的 Base64 图像数据长度。",
      "description_en": "Calculate the Base64 image data length for a given image size."
    },
    {
      "action_name": "auto-initCam",
      "description": "初始化相机并应用基础成像设置。",
      "description_en": "Initialize the camera and apply basic imaging settings."
    },
    {
      "action_name": "auto-put_frame",
      "description": "写入一帧图像数据供当前采集流程使用。",
      "description_en": "Provide one image frame for the current acquisition workflow."
    },
    {
      "action_name": "auto-start_live",
      "description": "开始实时图像采集与预览。",
      "description_en": "Start live image acquisition and preview."
    },
    {
      "action_name": "auto-stop_live",
      "description": "停止实时图像采集与预览。",
      "description_en": "Stop live image acquisition and preview."
    },
    {
      "action_name": "auto-suspend_live",
      "description": "暂停实时图像采集。",
      "description_en": "Suspend live image acquisition."
    },
    {
      "action_name": "auto-prepare_live",
      "description": "为实时采集做准备。",
      "description_en": "Prepare the camera for live acquisition."
    },
    {
      "action_name": "auto-close",
      "description": "关闭相机连接。",
      "description_en": "Close the camera connection."
    },
    {
      "action_name": "auto-setPropertyValue",
      "description": "设置指定相机属性。",
      "description_en": "Set a specified camera property."
    },
    {
      "action_name": "auto-getPropertyValue",
      "description": "读取指定相机属性。",
      "description_en": "Get a specified camera property."
    },
    {
      "action_name": "auto-set_exposure_time",
      "description": "设置曝光时间。",
      "description_en": "Set the exposure time."
    },
    {
      "action_name": "auto-set_analog_gain",
      "description": "设置模拟增益。",
      "description_en": "Set the analog gain."
    },
    {
      "action_name": "auto-getLast",
      "description": "获取最近一帧图像。",
      "description_en": "Get the most recent image frame."
    },
    {
      "action_name": "auto-startStreamingThread",
      "description": "启动连续图像流接收。",
      "description_en": "Start continuous image stream reception."
    },
    {
      "action_name": "auto-getLastChunk",
      "description": "获取最近接收的一段图像数据。",
      "description_en": "Get the most recently received chunk of image data."
    },
    {
      "action_name": "auto-setROI",
      "description": "设置感兴趣区域（ROI）。",
      "description_en": "Set the region of interest (ROI)."
    }
  ]
}

